function executeSkill(context) {
  var caster = context.piece;
  var player = battle.players.find(function(item) { return item.playerId === caster.ownerPlayerId; });
  if (!player) return { success: false, message: '未找到玩家' };
  var holyCards = player.hand.filter(function(card) { return ['holy-smite', 'holy-heal', 'holy-charge'].indexOf(card.cardId) !== -1; });
  if (holyCards.length === 0) return { success: false, message: '没有圣光手牌' };
  var options = holyCards.map(function(card) { return { label: card.name || card.cardId, value: card.instanceId }; });
  var choice = selectOption({ title: '穆鲁的挽歌：选择要丢弃的圣光手牌', options: options, selectionMode: 'multi', presentation: 'hand', minSelections: 1, maxSelections: Math.min(4, holyCards.length), canCancel: true });
  if (choice === undefined || choice === null || choice.needsOptionSelection) return choice;
  if (!Array.isArray(choice) || choice.length < 1 || choice.length > 4) return { success: false, message: '穆鲁的挽歌选择无效' };
  var unique = [];
  for (var i = 0; i < choice.length; i++) { if (unique.indexOf(choice[i]) !== -1) return { success: false, message: '不能重复选择同一张手牌' }; unique.push(choice[i]); }
  var selected = unique.map(function(id) { return holyCards.find(function(card) { return card.instanceId === id; }); });
  if (selected.some(function(card) { return !card; })) return { success: false, message: '选择的圣光手牌已失效' };
  selected.forEach(function(card) { discardCard(card.instanceId); });
  var totalDamage = 0; var totalHeal = 0;
  for (var step = 0; step < selected.length; step++) {
    var enemies = battle.pieces.filter(function(piece) { return piece.ownerPlayerId !== caster.ownerPlayerId && piece.currentHp > 0; });
    var allies = battle.pieces.filter(function(piece) { return piece.ownerPlayerId === caster.ownerPlayerId && piece.currentHp > 0; });
    if (enemies.length > 0) { var damageResult = dealDamage(caster, enemies, 2, 'true', battle, 'muru-lament'); totalDamage += damageResult.totalDamage || 0; }
    if (allies.length > 0) { var healResult = healDamage(caster, allies, 2, battle, 'muru-lament'); totalHeal += healResult.totalHeal || 0; }
  }
  if (selected.length >= 3) {
    battle.pieces.filter(function(piece) { return piece.ownerPlayerId === caster.ownerPlayerId && piece.currentHp > 0; }).forEach(function(ally) {
      var shield = ally.statusTags && ally.statusTags.find(function(tag) { return tag.type === 'divine-shield'; });
      if (!shield) { addStatusEffectById(ally.instanceId, { id: 'divine-shield', name: '圣盾', type: 'divine-shield', currentDuration: -1, currentUses: -1, intensity: 1, stacks: 1, relatedRules: ['rule-divine-shield'] }); addRuleById(ally.instanceId, 'rule-divine-shield'); }
    });
    var extractionState = caster.skills && caster.skills.find(function(skill) { return skill.skillId === 'light-extraction'; });
    if (extractionState) extractionState.currentCooldown = 0;
  }
  return { success: true, message: caster.name + '发动穆鲁的挽歌，丢弃' + selected.length + '张圣光手牌，造成' + totalDamage + '点伤害并恢复' + totalHeal + '点生命' };
}
